select jsonb_build_object(
 'migrations',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations),
 'application_tables',(select count(*) from pg_tables where schemaname='public'),
 'rls_disabled',(select count(*) from pg_tables where schemaname='public' and not rowsecurity),
 'foreign_keys',(select count(*) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and contype='f'),
 'policies',(select count(*) from pg_policies where schemaname='public'),
 'public_functions',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
 'publication',(select jsonb_build_object('insert',pubinsert,'update',pubupdate,'delete',pubdelete,'truncate',pubtruncate,'all_tables',puballtables) from pg_publication where pubname='supabase_realtime'),
 'published_tables',(select jsonb_agg(tablename order by tablename) from pg_publication_tables where pubname='supabase_realtime'),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'limit',file_size_limit,'mime',allowed_mime_types) order by id) from storage.buckets),
 'storage_policies',(select jsonb_agg(jsonb_build_object('name',policyname,'cmd',cmd,'roles',roles) order by policyname) from pg_policies where schemaname='storage' and tablename='objects'),
 'unsafe_definers',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not coalesce(p.proconfig @> array['search_path=""'],false)),
 'capabilities_anonymous',has_function_privilege('anon','public.phase4_capabilities()','EXECUTE'),
 'capabilities_authenticated',has_function_privilege('authenticated','public.phase4_capabilities()','EXECUTE'),
 'invalid_constraints',(select count(*) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and not convalidated),
 'invalid_indexes',(select count(*) from pg_index i join pg_class t on t.oid=i.indrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and (not i.indisvalid or not i.indisready)),
 'public_execute_grants',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where n.nspname in ('public','private') and a.grantee=0 and a.privilege_type='EXECUTE'),
 'storage_objects_rls',(select relrowsecurity from pg_class where oid='storage.objects'::regclass),
 'browser_direct_avatar_write',has_column_privilege('authenticated','public.profiles','avatar_path','UPDATE'),
 'browser_direct_images_write',has_table_privilege('authenticated','public.property_images','INSERT,UPDATE,DELETE'),
 'browser_direct_staging_write',has_table_privilege('authenticated','public.media_uploads','INSERT,UPDATE,DELETE'),
 'browser_direct_room_images_write',has_table_privilege('authenticated','public.room_images','INSERT,UPDATE,DELETE'),
 'browser_private_property_bypass',has_function_privilege('authenticated','private.save_property_local(jsonb)','EXECUTE'),
 'browser_private_room_bypass',has_function_privilege('authenticated','private.save_room_local(jsonb)','EXECUTE'),
 'anon_upload',has_function_privilege('anon','public.begin_media_upload(text,uuid,text,integer)','EXECUTE'),
 'anon_send_media',has_function_privilege('anon','public.send_message_media(uuid,text,uuid,uuid[])','EXECUTE'),
 'anon_avatar_directory',has_function_privilege('anon','public.conversation_avatars(uuid)','EXECUTE'),
 'browser_server_payment',has_function_privilege('authenticated','public.server_record_rent_payment(uuid,text,boolean,text,boolean,timestamptz)','EXECUTE')
) as phase4_postflight;
